  '每回合提供 100 资金。可生产舰船。停留的己方舰船与步兵类单位每回合恢复 2 HP（需支付资金）。': '매 턴 자금 100 제공. 함선 생산 가능. 머무는 아군 함선과 보병류 유닛은 매 턴 HP 2 회복(자금 지불 필요).',  // TERRAIN.port.note
