  '抛射：移动后仍可攻击。': '투척: 이동 후에도 공격 가능.',  // codex.js:169
  '不可攻击相邻的敌方单位，受到相邻敌方单位攻击时也不可反击。': '인접한 적군 유닛 공격 불가. 인접한 적군 유닛에게 공격받아도 반격 불가.',  // codex.js:170
  '攻击时无视目标的地形防御。': '공격 시 목표의 지형 방어 무시.',  // codex.js:171
  '所有阵营均可研究。': '모든 진영이 연구 가능.',  // codex.js:196
  '通用与阵营': '공통 및 진영',  // codex.js:204
  '克制表　行为攻击方，列为防守方，数值为基础伤害（%）': '상성표　행은 공격 측, 열은 방어 측, 수치는 기본 피해(%)',  // codex.js:211
  '攻 ＼ 守': '공격 \\ 방어',  // codex.js:211
  '胜负': '승패',  // codex.js:235
  '设有天数上限时，到期后先比较各队的收入建筑数，再比较单位总造价。': '일수 제한이 있으면 기한이 된 뒤 먼저 각 팀의 수입 건물 수를, 다음으로 유닛 총 생산비를 비교한다.',  // codex.js:238
  '每座建筑有 20 点占领值，每次占领减去单位当前的 HP。满 HP 的单位需 2 回合完成占领。': '건물마다 점령치가 20 있고, 점령할 때마다 유닛의 현재 HP만큼 줄어든다. 최대 HP인 유닛은 2턴이면 점령을 마친다.',  // codex.js:247
  '占领中的单位离开或被击毁时，占领值恢复为 20。不可占领友方的建筑。': '점령 중인 유닛이 떠나거나 격파되면 점령치는 20으로 돌아간다. 동맹군의 건물은 점령 불가.',  // codex.js:248
  '两个单位的 HP 相加，超过 10 的部分按造价返还资金。': '두 유닛의 HP를 더하고, 10을 넘는 만큼은 생산비에 따라 자금으로 반환.',  // codex.js:250
  '受到不相邻的敌方单位攻击时不可反击。': '인접하지 않은 적군 유닛에게 공격받으면 반격 불가.',  // codex.js:260
  '己方雷达塔 5 格范围内的己方单位攻击 +10%。多座雷达塔的效果不叠加。': '아군 레이더 탑 5칸 범위 안의 아군 유닛 공격 +10%. 레이더 탑 여럿의 효과는 중첩되지 않는다.',  // codex.js:276
  '迷雾开启时，己方雷达塔可看见周围 5 格。': '안개가 켜져 있으면 아군 레이더 탑은 주위 5칸이 보인다.',  // codex.js:276
  '不提供收入。': '수입 제공 없음.',  // codex.js:276
  '可占领建筑的兵种进入后可发射一次：指定一格为中心，2 格内所有单位各损失 3 HP。': '건물 점령이 가능한 병종이 진입하면 한 번 발사 가능: 지정한 칸을 중심으로 2칸 안의 모든 유닛이 각각 HP 3 손실.',  // codex.js:277
  '每击毁一个敌方单位，星级 +1，最高 3 星。': '적군 유닛을 하나 격파할 때마다 성급 +1, 최대 3성.',  // codex.js:278
  '每 1 星攻击 +5%、防御 +5%。': '1성마다 공격 +5%, 방어 +5%.',  // codex.js:278
  '运输单位移动后选择“卸载”，将搭载的单位放置到相邻且可进入的空格。卸载的单位本回合不可再行动。': '수송 유닛은 이동 후 “하차”를 선택해, 탑재한 유닛을 인접해 있고 진입 가능한 빈칸에 내려놓는다. 하차한 유닛은 이번 턴 더 행동할 수 없다.',  // codex.js:282
  '技能槽积满后，可在己方回合发动技能，效果持续至己方下回合开始。': '스킬 게이지가 가득 차면 아군 턴에 스킬 발동 가능. 효과는 다음 아군 턴 시작까지 지속.',  // codex.js:284
  '技能仅对己方阵营生效。各指挥官的技能见“指挥官”页。': '스킬은 아군 진영에만 적용된다. 지휘관별 스킬은 “지휘관” 페이지 참조.',  // codex.js:284
  '特长与阵营特性': '특기와 진영 특성',  // codex.js:285
  '每位指挥官拥有一项特长，开局即生效。': '지휘관마다 특기가 하나 있으며 게임 시작부터 적용된다.',  // codex.js:286
  '指挥官同时具有所属阵营的特性，与本局军队的颜色无关。': '지휘관은 소속 진영의 특성도 함께 가지며, 이번 게임의 군대 색과는 무관하다.',  // codex.js:287
  '研究点来源：研究经费、己方科研所，以及各阵营的研究方式（见“阵营”页）。': '연구 포인트의 출처: 연구비, 아군 연구소, 진영별 연구 방식(“진영” 페이지 참조).',  // codex.js:294
  '多阵营与结盟': '다진영과 동맹',  // codex.js:308
  '同队阵营不可互相攻击，不可占领友方的建筑。可穿过友方单位所在的格子，但不可停留。': '같은 팀 진영끼리는 서로 공격 불가, 동맹군의 건물 점령 불가. 동맹군 유닛이 있는 칸은 통과할 수 있지만 머물 수 없다.',  // codex.js:310
  '迷雾开启时，同队阵营共享视野。': '안개가 켜져 있으면 같은 팀 진영은 시야를 공유한다.',  // codex.js:311
  '推进战役后解锁。': '캠페인을 진행하면 해금.',  // codex.js:329
