  '仅可看见己方单位和建筑周围的格子。森林、礁石、废墟中的敌方单位仅在相邻时可被发现，视野范围再大也看不到。': '아군 유닛과 건물 주위의 칸만 보인다. 숲, 암초, 폐허에 있는 적군 유닛은 인접해야만 발견되며, 시야가 아무리 넓어도 떨어져 있으면 보이지 않는다.',
  '开局时各阵营持有的资金。': '게임 시작 시 각 진영이 보유하는 자금.',  // ui-front.js:250
  '到达天数上限时，按建筑数和单位总造价判定胜负。选择“无”则不设上限。': '일수 제한에 도달하면 건물 수와 유닛 총 생산비로 승패 판정. “없음”을 선택하면 제한 없음.',  // ui-front.js:251
  '攻击和受到攻击均可积累技能槽，积满后可发动指挥官技能。': '공격할 때와 공격받을 때 모두 스킬 게이지가 축적되고, 가득 차면 지휘관 스킬 발동 가능.',  // ui-front.js:251
  '指挥官的特长与阵营特性。关闭后各阵营的数值相同。': '지휘관의 특기와 진영 특성. 끄면 모든 진영의 수치가 같아진다.',  // ui-front.js:251
  '支付研究经费获得研究点，解锁通用、阵营、指挥官三类科技。': '연구비를 지불해 연구 포인트를 얻고 공통, 진영, 지휘관 세 종류의 기술을 해금.',  // ui-front.js:252
  '阵营数较少的队伍开局资金增加，每回合收入也略有增加。': '진영 수가 적은 팀은 초기 자금이 늘고 턴 수입도 조금 늘어난다.',  // ui-front.js:252
  '三支及以上队伍对战时，击毁敌方单位可获得其造价的一部分资金。': '세 팀 이상이 싸울 때 적군 유닛을 격파하면 그 생산비의 일부를 자금으로 획득.',  // ui-front.js:252
  '已恢复推荐设置': '추천 설정으로 복원됨',  // ui-front.js:260
  '开始演示': '데모 시작',  // ui-front.js:290
  '开始观战': '관전 시작',  // ui-front.js:290
  '也可以点右上角的喇叭图标开关。': '오른쪽 위의 스피커 아이콘으로도 켜고 끌 수 있음.',
  '背景音乐的音量，不影响音效。': '배경 음악의 음량. 효과음에는 영향 없음.',  // ui-front.js:303
  '移动、攻击等动画的播放速度。': '이동, 공격 등 애니메이션의 재생 속도.',  // ui-front.js:304
  '电脑加速': '컴퓨터 가속',  // ui-front.js:305
  '电脑回合以 4 倍速播放。': '컴퓨터 턴을 4배속으로 재생.',  // ui-front.js:305
  '镜头跟随电脑': '컴퓨터 따라가기',  // ui-front.js:306
  '电脑行动时，镜头自动跟随。': '컴퓨터가 행동할 때 카메라가 자동으로 따라간다.',  // ui-front.js:306
  '在地图上显示格线。': '맵에 격자를 표시.',  // ui-front.js:307
  '转场动画': '전환 연출',  // ui-front.js:308
  '开战、回合切换、胜负时的阵营色横条和大字。关闭后回合切换改为普通横幅。': '전투 개시, 턴 전환, 승패 때 나오는 진영 색 띠와 큰 글자. 끄면 턴 전환이 일반 배너로 바뀐다.',  // ui-front.js:308
  '常显按键提示': '조작 안내 항상 표시',  // ui-front.js:309
  '关：仅在菜单、选择目标等场合显示按键提示。开：对局中始终显示。': '끄기: 메뉴, 목표 선택 등에서만 조작 안내 표시. 켜기: 게임 중 항상 표시.',  // ui-front.js:309
  '每格的显示大小。选择“自动”时，一屏约显示 15×10 格。': '칸 하나의 표시 크기. “자동”을 선택하면 한 화면에 약 15×10칸 표시.',  // ui-front.js:310
