  '已被拾取的碎片堆，与荒地相同。轮式车辆的移动消耗为 3。': '이미 주운 조각 더미. 황무지와 동일. 차륜 차량의 이동 비용은 3.',
  '{res}不足': '{res} 부족',
  '这一局不能这样做': '이번 게임에서는 할 수 없음',
  '中央海与陨星碎片': '중앙해와 운석 조각',
  '每座收入建筑每回合提供的资金，陨星矿为 2 倍。': '수입 건물마다 매 턴 제공하는 자금. 운석 광산은 2배.',
  '海眼中心亮起一圈灯。那不是任何一国的灯。': '바다의 눈 한가운데에 등불이 둥글게 켜졌다. 어느 나라의 등불도 아니었다.',
  '（与荒地相同）。轮式车辆的移动消耗为 3。': '(황무지와 동일)로 변한다. 차륜 차량의 이동 비용은 3.',
