  '迷雾开启时，可发现周围 8 格{list}中的隐蔽单位。': '안개가 켜져 있으면 주위 8칸의 {list}에 있는 은폐 유닛 발견 가능.',
  '迷雾开启时，可发现周围 8 格中的隐蔽单位。': '안개가 켜져 있으면 주위 8칸에 있는 은폐 유닛 발견 가능.',
