  '{list}攻击时，无视目标的地形防御。': '{list}의 공격은 목표의 지형 방어를 무시한다.',
  '位于己方或中立{fort}的单位，受到的反击伤害减半。': '아군 또는 중립 {fort}에 있는 유닛이 받는 반격 피해 절반.',
  '射程大于 1 的单位：{list}。': '사거리가 1보다 큰 유닛: {list}.',
  '{fort}上的远程单位、{mountain}上的步兵类远程单位射程 +1，两者不叠加。': '{fort}에 있는 원거리 유닛, {mountain}에 있는 보병류 원거리 유닛 사거리 +1. 둘은 중첩되지 않는다.',
  '{fort}上的远程单位射程 +1，两者不叠加。': '{fort}에 있는 원거리 유닛 사거리 +1. 둘은 중첩되지 않는다.',
  '{mountain}上的步兵类远程单位射程 +1，两者不叠加。': '{mountain}에 있는 보병류 원거리 유닛 사거리 +1. 둘은 중첩되지 않는다.',
  '车辆在{land}修理，航空单位在{airport}修理，舰船在{port}修理。步兵类单位可在任意己方建筑修理。': '차량은 {land}에서, 항공 유닛은 {airport}에서, 함선은 {port}에서 수리. 보병류 유닛은 모든 아군 건물에서 수리 가능.',
  '车辆在{land}修理，航空单位在{airport}修理。步兵类单位可在任意己方建筑修理。': '차량은 {land}에서, 항공 유닛은 {airport}에서 수리. 보병류 유닛은 모든 아군 건물에서 수리 가능.',
  '车辆在{land}修理，舰船在{port}修理。步兵类单位可在任意己方建筑修理。': '차량은 {land}에서, 함선은 {port}에서 수리. 보병류 유닛은 모든 아군 건물에서 수리 가능.',
  '车辆在{land}修理。步兵类单位可在任意己方建筑修理。': '차량은 {land}에서 수리. 보병류 유닛은 모든 아군 건물에서 수리 가능.',
  '与{name}相邻的己方车辆、航空单位、舰船每回合恢复 1 HP（无需支付资金）。': '{name}에 인접한 아군 차량, 항공 유닛, 함선은 매 턴 HP 1 회복(자금 지불 불필요).',
  '与{name}相邻的己方步兵类单位每回合恢复 2 HP（无需支付资金）。多名{name}的效果不叠加。': '{name}에 인접한 아군 보병류 유닛은 매 턴 HP 2 회복(자금 지불 불필요). {name} 여럿의 효과는 중첩되지 않는다.',
  '{name}可搭载 {n} 个陆上单位': '{name}: 지상 유닛 {n}개 탑재 가능',
  '{name}可搭载 {n} 个步兵类单位': '{name}: 보병류 유닛 {n}개 탑재 가능',
  '每座己方{lab}每回合提供 {pts} 研究点，最多计 {max} 座。': '아군 {lab}마다 매 턴 연구 포인트 {pts} 제공, 최대 {max}곳까지 계산.',
  '击毁敌方的强化单位时，获得它强化价的一半（向上取整）。运输单位搭载的强化单位各自计算。': '적군의 강화 유닛을 격파하면 그 강화 비용의 절반(올림)을 얻는다. 수송 유닛에 탑재된 강화 유닛은 각각 따로 계산한다.',
  '步兵类单位在{mountain}上视野 +3。己方建筑可看见所在的一格，{hq}可看见周围 2 格，{tower}可看见周围 5 格。': '보병류 유닛은 {mountain}에서 시야 +3. 아군 건물의 시야: 자신이 있는 한 칸({hq}: 주위 2칸, {tower}: 주위 5칸).',
  '步兵类单位在{mountain}上视野 +3。己方建筑可看见所在的一格，{hq}可看见周围 2 格。': '보병류 유닛은 {mountain}에서 시야 +3. 아군 건물의 시야: 자신이 있는 한 칸({hq}: 주위 2칸).',
  '步兵类单位在{mountain}上视野 +3。己方建筑可看见所在的一格，{tower}可看见周围 5 格。': '보병류 유닛은 {mountain}에서 시야 +3. 아군 건물의 시야: 자신이 있는 한 칸({tower}: 주위 5칸).',
  '步兵类单位在{mountain}上视野 +3。己方建筑可看见所在的一格。': '보병류 유닛은 {mountain}에서 시야 +3. 아군 건물의 시야: 자신이 있는 한 칸.',
  '己方建筑可看见所在的一格，{hq}可看见周围 2 格，{tower}可看见周围 5 格。': '아군 건물의 시야: 자신이 있는 한 칸({hq}: 주위 2칸, {tower}: 주위 5칸).',
  '己方建筑可看见所在的一格，{hq}可看见周围 2 格。': '아군 건물의 시야: 자신이 있는 한 칸({hq}: 주위 2칸).',
  '己方建筑可看见所在的一格，{tower}可看见周围 5 格。': '아군 건물의 시야: 자신이 있는 한 칸({tower}: 주위 5칸).',
