  '{name}开闸放水：{cells} 格变为海洋，{pushed} 个单位被推开': '{name} 수문 개방: {cells}칸이 바다로 변함, 유닛 {pushed}개가 밀려남',
  '{name}开闸放水：{cells} 格变为海洋，{lost} 个单位被击毁': '{name} 수문 개방: {cells}칸이 바다로 변함, 유닛 {lost}개 격파됨',
