  '涨潮：{cells} 格变为海洋，{pushed} 个单位被推开，{lost} 个单位被击毁': '수위 상승: {cells}칸이 바다로 변함, 유닛 {pushed}개가 밀려남, 유닛 {lost}개 격파됨',
  '涨潮：{cells} 格变为海洋，{pushed} 个单位被推开': '수위 상승: {cells}칸이 바다로 변함, 유닛 {pushed}개가 밀려남',
