// ── 故事与战役（lore.js、campaign.js）及改名后重新对齐的条目 ──由 tools/i18n-story.js merge 回填，固定台词见 tools/I18N-GLOSSARY.md
AWI18n.add('ko', {
  '收购。开个价，车归我了。': '인수합니다. 값은 제가 매기죠. 차는 이제 제 겁니다.',
  '射程 3–6，只能攻击航空单位，伤害极高。移动后不可攻击。': '사거리 3–6. 항공 유닛만 공격 가능. 피해가 매우 높다. 이동 후 공격 불가.',
  '只能攻击航空单位，用于争夺制空权。': '항공 유닛만 공격 가능. 제공권 다툼에 쓴다.',
  '只能攻击舰船，擅长攻击战列舰。航空单位和战列舰不可攻击潜艇。不敌驱逐舰。': '함선만 공격 가능. 전함 공격에 강하다. 항공 유닛과 전함은 잠수함 공격 불가. 구축함에 약하다.',
  '只能在道路、桥梁和建筑上移动。射程 1–3，移动后只能攻击相邻目标。可搭载 2 个徒步的步兵类单位（摩托兵除外）。攻击与防御介于中型坦克和重型坦克之间。': '도로, 다리, 건물 칸에서만 이동 가능. 사거리 1–3, 이동 후에는 인접한 목표만 공격 가능. 도보 보병류 유닛(바이크병 제외) 2개 탑재 가능. 공격과 방어는 중형전차와 중전차의 중간.',
  '隐形的航空单位：敌方只有相邻时才能发现（迷雾关闭时也有效）。对航空单位伤害高，对陆上单位伤害中等。': '은신 항공 유닛: 적군은 인접해야만 발견할 수 있다(안개가 꺼져 있어도 적용). 항공 유닛에 주는 피해가 높고, 지상 유닛에 주는 피해는 중간.',
  '射程 2–5 的舰船，移动后不可攻击。上一个己方回合没有攻击时处于下潜状态：敌方只有相邻时才能发现（迷雾关闭时也有效）。': '사거리 2–5의 함선. 이동 후 공격 불가. 직전 아군 턴에 공격하지 않았으면 잠항 상태가 된다: 적군은 인접해야만 발견할 수 있다(안개가 꺼져 있어도 적용).',
  '陆上单位结束移动停在这一格时拾取，获得 1–3 份陨星碎片（每个碎片堆在开局时随机决定），这一格变为碎片坑（与荒地相同）。轮式车辆的移动消耗为 3。': '지상 유닛이 이동을 마치고 이 칸에 머물면 줍는다. 운석 조각 1–3개 획득(조각 더미마다 게임 시작 시 무작위로 결정), 이 칸은 조각 구덩이(황무지와 동일)로 변한다. 차륜 차량의 이동 비용은 3.',
  '迷雾开启时，森林中的单位只有相邻时才会被发现。': '안개가 켜져 있으면 숲에 있는 유닛은 인접해야만 발견된다.',
  '只有步兵类单位可以进入。狙击手、投弹手在山地上射程 +1。迷雾开启时，步兵类单位在山地上视野 +3。': '보병류 유닛만 진입 가능. 저격수, 척탄병은 산지에서 사거리 +1. 안개가 켜져 있으면 보병류 유닛은 산지에서 시야 +3.',
  '登陆艇可以进入。陆上单位可以在这里搭乘登陆艇；登陆艇可以在这里把搭载的单位卸载到相邻的格子。': '상륙정 진입 가능. 지상 유닛은 여기서 상륙정에 탑승 가능. 상륙정은 여기서 탑재한 유닛을 인접 칸에 하차 가능.',
  '只有舰船可以进入，移动消耗 2，地形防御 2 星。': '함선만 진입 가능. 이동 비용 2, 지형 방어 2성.',
  '每回合提供 3 研究点（每个阵营最多计 3 座）。停留的己方步兵类单位每回合恢复 2 HP（需支付资金）。可以在这里研究科技。': '매 턴 연구 포인트 3 제공(진영마다 최대 3곳까지 계산). 머무는 아군 보병류 유닛은 매 턴 HP 2 회복(자금 지불 필요). 여기서 기술 연구 가능.',
  '这一局没有开启科技': '이번 게임은 기술 꺼짐',
  '这一局关闭了指挥官特长': '이번 게임은 지휘관 특기 꺼짐',
  '这一局关闭了指挥官技能': '이번 게임은 지휘관 스킬 꺼짐',
  '和「{name}」只能选一个': '“{name}” 기술과 둘 중 하나만 선택 가능',
  '要先解锁「{name}」': '“{name}” 먼저 해금 필요',
  '只能在己方回合解锁科技': '기술 해금은 아군 턴에만 가능',
  '这项科技不在己方的科技树里': '아군 기술 트리에 없는 기술',
  '这项科技已解锁': '이미 해금한 기술',
  '这里不能生产这个兵种': '여기서는 이 병종 생산 불가',
  '这一格有单位': '이 칸에 유닛이 있음',
  '这座建筑本回合已经生产过了': '이 건물은 이번 턴에 이미 생산함',
  '全军立即恢复 2 HP。己方下回合开始前：全军防御 +20%。': '전군 즉시 HP 2 회복. 다음 아군 턴 시작 전까지: 전군 방어 +20%.',
  '立即获得「己方建筑数 × 80」的资金，再加回合收入的 20%。': '즉시 “아군 건물 수 × 80”의 자금 획득. 여기에 턴 수입의 20% 추가.',
  '所有敌方单位各损失 1 HP（不会被击毁）。有两个敌方阵营时各 0.8 HP，三个时各 0.7 HP。本回合：己方远程单位攻击 +30%。': '모든 적군 유닛이 각각 HP 1 손실(격파되지 않음). 적군 진영이 둘이면 각각 HP 0.8, 셋이면 각각 HP 0.7. 이번 턴: 아군 원거리 유닛 공격 +30%.',
  '全军立即恢复 2 HP（舰船 3 HP）。本回合：全军移动力 +1（舰船 +2），舰船对陆上单位伤害 +30%。己方下回合开始前：全军防御 +10%。': '전군 즉시 HP 2 회복(함선은 HP 3). 이번 턴: 전군 이동력 +1(함선 +2), 함선이 지상 유닛에 주는 피해 +30%. 다음 아군 턴 시작 전까지: 전군 방어 +10%.',
  '本回合：航空单位移动力 +2、攻击 +50%，攻击时不受反击。其他单位移动力 +2、攻击 +30%。': '이번 턴: 항공 유닛 이동력 +2, 공격 +50%, 공격 시 반격받지 않음. 그 외 유닛 이동력 +2, 공격 +30%.',
  '本回合：各型坦克移动力 +2、攻击 +50%，攻击后可再移动。己方下回合开始前：各型坦克防御 +20%。': '이번 턴: 경전차, 중형전차, 중전차 이동력 +2, 공격 +50%, 공격 후 재이동 가능. 다음 아군 턴 시작 전까지: 경전차, 중형전차, 중전차 방어 +20%.',
  '最多 4 座没有单位的己方城市各出现一个满 HP 的步兵，当回合可行动。本回合：步兵类单位攻击 +30%、移动力 +1。': '유닛이 없는 아군 도시 최대 4곳에 최대 HP의 보병이 하나씩 출현. 그 턴에 행동 가능. 이번 턴: 보병류 유닛 공격 +30%, 이동력 +1.',
  '本回合：全军攻击 +20%。己方下回合开始前：敌方单位视野降为 1。迷雾关闭时，敌方只能发现自己单位 2 格内的己方单位。': '이번 턴: 전군 공격 +20%. 다음 아군 턴 시작 전까지: 적군 유닛의 시야가 1로 감소. 안개가 꺼져 있으면 적군은 자기 유닛에서 2칸 안의 아군 유닛만 발견 가능.',
  '本回合：全军移动力 +2，攻击时不受反击。': '이번 턴: 전군 이동력 +2, 공격 시 반격받지 않음.',
  '己方下回合开始前：己方反击伤害 ×2，全军防御 +20%。': '다음 아군 턴 시작 전까지: 아군 반격 피해 ×2, 전군 방어 +20%.',
  '己方下回合开始前：敌方单位移动力 −3（最低 1）、视野 −2，己方全军防御 +20%。': '다음 아군 턴 시작 전까지: 적군 유닛 이동력 −3(최소 1), 시야 −2, 아군 전군 방어 +20%.',
  '本回合：HP 未满的己方单位攻击 +50%，全军移动力 +1。': '이번 턴: 최대 HP 미만인 아군 유닛 공격 +50%, 전군 이동력 +1.',
  '本回合：全军攻击 +20%（舰船 +40%）、移动力 +2。己方下回合开始前：敌方舰船移动力 −3（最低 1），不能在港口修理。': '이번 턴: 전군 공격 +20%(함선 +40%), 이동력 +2. 다음 아군 턴 시작 전까지: 적군 함선 이동력 −3(최소 1), 항구에서 수리 불가.',
  '己方下回合开始前：敌方单位在道路、桥梁上的移动消耗 +2（航空单位除外）。本回合：己方车辆攻击 +30%。': '다음 아군 턴 시작 전까지: 적군 유닛의 도로, 다리 이동 비용 +2(항공 유닛 제외). 이번 턴: 아군 차량 공격 +30%.',
  '解锁黑潮后可查看。完成任意一组条件就能解锁：': '흑조를 해금하면 볼 수 있다. 둘 중 하나만 달성하면 해금된다:',
  '所有阵营都能研究。': '모든 진영이 연구 가능.',
  '两条科技线的第 3 级只能选一条。': '두 기술 계열의 3단계는 하나만 선택 가능.',
  '司令部被占领时，败北阵营的单位全部消失，建筑归占领方所有。全部单位被击毁时，这个阵营的建筑全部变为中立。': '사령부가 점령되면 패배한 진영의 유닛은 전부 사라지고 건물은 점령한 쪽의 소유가 된다. 유닛이 전부 격파되면 그 진영의 건물은 전부 중립이 된다.',
  '每座收入建筑每回合提供 {n} 资金，在回合开始时获得。这个数值可以在开局设置里调整。': '수입 건물마다 매 턴 자금 {n} 제공. 턴 시작 시 획득. 이 수치는 게임 시작 설정에서 조정 가능.',
  '把单位移动到同兵种、HP 未满的己方单位所在的格子，选择“合并”。': '같은 병종이고 최대 HP 미만인 아군 유닛이 있는 칸으로 유닛을 이동시킨 뒤 “합류” 선택.',
  '两个单位都是强化单位，合并后才保留强化。': '두 유닛이 모두 강화 유닛이어야 합류 후에도 강화가 유지된다.',
  '攻击加成：位于己方{tower} 5 格范围内时 +10%，单位每 1 星 +5%，再加上指挥官的修正。': '공격 보너스: 아군 {tower} 5칸 범위 안에 있으면 +10%, 유닛 1성마다 +5%, 여기에 지휘관 보정을 더한다.',
  '攻击加成：单位每 1 星 +5%，再加上指挥官的修正。': '공격 보너스: 유닛 1성마다 +5%, 여기에 지휘관 보정을 더한다.',
  '防御加成：单位每 1 星 +5%，再加上指挥官的修正，最高 70%。': '방어 보너스: 유닛 1성마다 +5%, 여기에 지휘관 보정을 더한다. 최대 70%.',
  '受到不相邻的敌方单位攻击时不可反击。{list}受到相邻敌方单位攻击时也不可反击。': '인접하지 않은 적군 유닛에게 공격받으면 반격 불가. {list}도 인접한 적군 유닛에게 공격받으면 반격 불가.',
  '不可攻击对方兵种的单位也不可反击。': '상대 병종을 공격할 수 없는 유닛도 반격 불가.',
  '回合开始时，停留在己方建筑的单位恢复 2 HP，每恢复 1 HP 需支付造价 10% 的资金；资金不足时只恢复 1 HP。': '턴 시작 시 아군 건물에 머무는 유닛은 HP 2 회복. HP 1 회복마다 생산비의 10%에 해당하는 자금 지불 필요. 자금이 부족하면 HP 1만 회복.',
  '每座只能使用一次，敌我单位都受影响。运输单位搭载的单位不受影响。': '사일로마다 한 번만 사용 가능. 적군과 아군 유닛 모두 영향을 받는다. 수송 유닛에 탑재된 유닛은 영향을 받지 않는다.',
  '把单位移动到己方运输单位所在的格子就能搭载。友方的运输单位不能搭载己方单位。': '아군 수송 유닛이 있는 칸으로 유닛을 이동시키면 탑재된다. 동맹군의 수송 유닛에는 아군 유닛을 탑재할 수 없다.',
  '攻击和受到攻击都能积累技能槽，积累量按损失的造价计算，受到攻击时是攻击时的 2 倍。': '공격할 때와 공격받을 때 모두 스킬 게이지가 축적된다. 축적량은 손실된 생산비 기준이며, 공격받을 때는 공격할 때의 2배.',
  '在己方{a}或{b}可以研究科技。': '아군 {a} 또는 {b}에서 기술 연구 가능.',
  '在己方{a}可以研究科技。': '아군 {a}에서 기술 연구 가능.',
  '每个阵营可研究 6 条科技线：通用 3 条、阵营 2 条、指挥官 1 条。每条科技线分 3 级，要按顺序解锁。': '진영마다 기술 계열 6개를 연구할 수 있다: 공통 3개, 진영 2개, 지휘관 1개. 계열마다 3단계이며 차례로 해금해야 한다.',
  '解锁科技需要研究点。研究点在每回合开始时获得，可以一直攒着。': '기술 해금에는 연구 포인트가 필요하다. 연구 포인트는 매 턴 시작 시 들어오며 계속 모아 둘 수 있다.',
  '研究点够一项科技所需的点数时，就能在己方回合立即解锁，当回合生效；一回合可以连续解锁多项。': '연구 포인트가 기술에 필요한 만큼 모이면 아군 턴에 바로 해금할 수 있고 그 턴부터 적용된다. 한 턴에 여러 개를 이어서 해금할 수 있다.',
  '阵营 2 条科技线的第 3 级只能选一条。': '진영 기술 계열 2개의 3단계는 둘 중 하나만 선택 가능.',
  '陆上单位结束移动停留在{shard}上就能拾取，获得 {min}–{max} 份（每个碎片堆在开局时随机决定），这一格变为{pit}。航空单位不拾取。': '지상 유닛이 이동을 마치고 {shard}에 머물면 줍는다. {min}–{max}개 획득(조각 더미마다 게임 시작 시 무작위로 결정), 이 칸은 {pit} 칸으로 변한다. 항공 유닛은 줍지 않는다.',
  '{name}已采完，变为山地': '{name} 고갈, 산지로 변함',
  '两个单位合并时，只要有一方是强化单位，合并后就是强化单位。双方都是强化单位时，返还其中一个单位的强化价。': '두 유닛을 합치면 한쪽만 강화 유닛이어도 합친 유닛은 강화 유닛이 된다. 둘 다 강화 유닛이면 한 유닛의 강화 비용을 돌려받는다.',
  '可以在开局规则里关闭{res}。': '게임 시작 규칙에서 {res} 끄기 가능.',
  '刚生产的单位，在做下一个动作之前可以按取消键撤回，资金和{res}全额返还。': '방금 생산한 유닛은 다음 행동을 하기 전까지 취소 버튼으로 되돌릴 수 있다. 자금과 {res} 전액 환불.',
  '单位移动后如果没有遇伏，也没有发现新的敌方单位，可以按取消键撤回这一步。': '이동 후 매복을 당하지 않았고 새 적군 유닛도 발견하지 않았다면, 그 이동도 취소 버튼으로 되돌릴 수 있다.',
  '做了下一个动作之后不能撤回。': '다음 행동을 한 뒤에는 되돌릴 수 없다.',
  '迷雾开启时，只能看见己方和友方的单位、建筑周围的格子。': '안개가 켜져 있으면 아군과 동맹군의 유닛, 건물 주위의 칸만 보인다.',
  '位于{list}的单位（航空单位除外）处于隐蔽状态，只有相邻时才会被发现。': '{list}에 있는 유닛(항공 유닛 제외)은 은폐 상태가 되어 인접해야만 발견된다.',
  '{sub}在任何位置都只有相邻时才会被发现，{dst}可以在 2 格内发现它。': '{sub}: 어느 위치에서든 인접해야만 발견된다. 단, {dst}에게는 2칸 안에서 발견된다.',
  '{sub}在任何位置都只有相邻时才会被发现。': '{sub}: 어느 위치에서든 인접해야만 발견된다.',
  '只能攻击看得见的目标。移动中遇到没有发现的敌方单位时停止移动（遇伏），这个单位本回合行动结束。': '보이는 목표만 공격 가능. 이동 중 발견하지 못한 적군 유닛과 마주치면 이동을 멈추고(매복 조우), 그 유닛은 이번 턴 행동이 끝난다.',
  '每张地图有 2–4 个阵营，按{list}的顺序行动。各阵营可以各自为战，也可以结盟组队。': '맵마다 진영 2–4개가 {list} 순서로 행동한다. 진영은 각자 싸울 수도, 동맹을 맺어 팀을 이룰 수도 있다.',
  '每张地图有 2–4 个阵营。各阵营可以各自为战，也可以结盟组队。': '맵마다 진영 2–4개. 진영은 각자 싸울 수도, 동맹을 맺어 팀을 이룰 수도 있다.',
  '战利品：三支及以上队伍对战时，击毁敌方单位可立即获得它造价 {pct}% 的资金。': '전리품: 세 팀 이상이 싸울 때 적군 유닛을 격파하면 즉시 그 생산비의 {pct}%를 자금으로 획득.',
  '{name}阵营、指挥官和精锐兵种要解锁后才能在自由对局中使用。完成下面任意一组条件就能解锁。': '{name} 진영, 지휘관, 정예 병종은 해금해야 자유 대전에서 쓸 수 있다. 아래 둘 중 하나만 달성하면 해금된다.',
  '这一关的地图「{name}」还没做好。': '이 스테이지의 맵 “{name}”: 아직 제작 중.',
  '这一关的地图还没做好': '이 스테이지의 맵은 아직 제작 중',
  '这一关暂时不能开始': '이 스테이지는 지금 시작할 수 없음',
  '按任意键开始': '아무 키나 눌러 시작',
  '点击屏幕开始': '화면을 터치해 시작',
  '2–4 个阵营': '2–4개 진영',
  '这张地图没有简介。': '이 맵은 소개가 없음.',
  '这张地图暂时不能使用，请选择其他地图。': '이 맵은 지금 사용할 수 없음. 다른 맵을 선택할 것.',
  '所有阵营都在同一队，至少要分成两队。': '모든 진영이 같은 팀. 최소 두 팀으로 나눠야 함.',
  '完成任意一组条件就能解锁：': '둘 중 하나만 달성하면 해금:',
  '开局时从这个阵营里随机选出一位指挥官。': '게임 시작 시 이 진영에서 지휘관 한 명을 랜덤으로 선택.',
  '这张地图的推荐设置：{list}': '이 맵의 추천 설정: {list}',
  '对局进度会自动保存，可以在标题画面选“继续”接着进行。': '게임 진행은 자동 저장된다. 타이틀 화면에서 “계속”을 선택하면 이어서 할 수 있다.',
  '每个提示都可以点击': '힌트는 모두 클릭 가능',
  '移动消耗都是 1': '이동 비용 모두 1',
  '开阔地形，陆上单位都能进入，地形防御 1 星。': '개활 지형. 지상 유닛 모두 진입 가능. 지형 방어 1성.',
  '陆上单位的移动消耗都是 1，没有地形防御。': '지상 유닛의 이동 비용 모두 1. 지형 방어 없음.',
  '跨越河流的道路，陆上单位的移动消耗都是 1，没有地形防御。': '강을 가로지르는 도로. 지상 유닛의 이동 비용 모두 1. 지형 방어 없음.',
  '徒步的步兵类单位可以进入，车辆和摩托兵不能进入。': '도보 보병류 유닛 진입 가능. 차량과 바이크병 진입 불가.',
  '只有舰船和航空单位可以进入。': '함선과 항공 유닛만 진입 가능.',
  '地形防御 2 星，车辆的移动消耗是 2。': '지형 방어 2성. 차량의 이동 비용은 2.',
  '可以在这里研究科技。': '여기서 기술 연구 가능.',
  '通关下面任意一关，同时解锁这位指挥官。': '아래 스테이지 중 하나를 클리어하면 이 지휘관도 함께 해금된다.',
  '电脑要在普通难度以上。': '컴퓨터는 보통 난이도 이상이어야 한다.',
  '要先解锁前一级': '이전 단계를 먼저 해금해야 함',
  '研究点够一项科技所需的点数时就能立即解锁，一回合可以连续解锁多项。': '연구 포인트가 기술에 필요한 만큼 모이면 바로 해금할 수 있다. 한 턴에 여러 개를 이어서 해금할 수 있다.',
  '现在不能解锁这项科技': '지금은 이 기술 해금 불가',
  '这张地图暂时不能使用（地图文件可能正在修改），请选择其他地图。': '이 맵은 지금 사용할 수 없음(맵 파일이 수정 중일 수 있음). 다른 맵을 선택할 것.',
  '这张地图需要 {n} 个阵营，现在不能开始对局，请选择其他地图。': '이 맵에는 진영 {n}개가 필요해 지금은 게임을 시작할 수 없다. 다른 맵을 선택해야 한다.',
  '这张地图暂时不能使用。': '이 맵은 지금 사용할 수 없음.',
  '要返回标题吗？': '타이틀로 돌아가시겠습니까?',
  '要认输吗？': '항복하시겠습니까?',
  '要出售这个单位吗？': '이 유닛을 매각하시겠습니까?',
  '还差{list}': '남은 진영: {list}',
  '车辆移动力 +1。步兵类单位攻击 −10%。': '차량 이동력 +1. 보병류 유닛 공격 −10%.',
  '位于 2 星及以上地形或建筑的单位防御 +20%。全军攻击 −10%。': '2성 이상 지형 또는 건물에 있는 유닛 방어 +20%. 전군 공격 −10%.',
  '所有单位造价 −10%。全军攻击 −10%。': '모든 유닛 생산비 −10%. 전군 공격 −10%.',
  '自行火炮、火箭炮攻击 +40%。其他远程单位攻击 +20%。': '자주포, 로켓포 공격 +40%. 그 외 원거리 유닛 공격 +20%.',
  '舰船攻击 +30%、防御 +20%、移动力 +1、造价 −15%，在港口修理免费。步兵类单位攻击 +10%。': '함선 공격 +30%, 방어 +20%, 이동력 +1, 생산비 −15%, 항구에서 수리 무료. 보병류 유닛 공격 +10%.',
  '攻击机、轰炸机、战斗机攻击 +30%、造价 −20%。': '공격기, 폭격기, 전투기 공격 +30%, 생산비 −20%.',
  '各型坦克攻击 +30%、防御 +10%。其他单位攻击 −15%。': '경전차, 중형전차, 중전차 공격 +30%, 방어 +10%. 그 외 유닛 공격 −15%.',
  '步兵类单位攻击 +30%、防御 +10%、占领值 ×1.5、视野 +1。车辆造价 +10%。': '보병류 유닛 공격 +30%, 방어 +10%, 점령치 ×1.5, 시야 +1. 차량 생산비 +10%.',
  '武装直升机攻击 +40%、防御 +20%、造价 −20%。运输直升机移动力 +2、搭载数 +1。舰船攻击和防御 −20%。': '공격 헬기 공격 +40%, 방어 +20%, 생산비 −20%. 수송 헬기 이동력 +2, 탑재 수 +1. 함선 공격과 방어 −20%.',
  '狙击手射程 +1、攻击 +40%、造价 −20%，移动后可攻击，击毁目标后可再行动（每回合一次）。投弹手攻击 +25%，其他步兵类单位攻击 +15%。全军视野 +1。位于森林、山地的己方单位防御 +15%。': '저격수 사거리 +1, 공격 +40%, 생산비 −20%, 이동 후 공격 가능, 목표 격파 후 재행동 가능(턴당 한 번). 척탄병 공격 +25%, 그 외 보병류 유닛 공격 +15%. 전군 시야 +1. 숲, 산지에 있는 아군 유닛 방어 +15%.',
  '新生产的单位当回合可行动。所有单位造价 +10%。': '새로 생산한 유닛은 그 턴에 행동 가능. 모든 유닛 생산비 +10%.',
  '直射单位攻击 +5%，攻击后可用剩余移动力再移动，但不能再攻击或占领。': '직사 유닛 공격 +5%. 공격 후 남은 이동력으로 재이동 가능. 단, 재공격과 점령은 불가.',
  '己方单位每回合开始时恢复 1 HP，在建筑上修理免费。全军攻击 −10%。': '아군 유닛은 매 턴 시작 시 HP 1 회복, 건물에서 수리 무료. 전군 공격 −10%.',
  '己方单位被相邻的敌方单位攻击时先手反击：先反击，敌方再按剩余 HP 攻击。己方主动攻击时攻击 −10%。': '아군 유닛이 인접한 적군 유닛에게 공격받으면 선제 반격: 먼저 반격하고, 적군은 남은 HP로 공격한다. 아군이 선공할 때는 공격 −10%.',
  '防空车、防空导弹、战斗机对航空单位伤害 +40%、视野 +2、造价 −25%。防空车对陆上单位伤害 +40%、防御 +15%、移动力 +1。直升机、攻击机、轰炸机攻击 −15%。': '자주대공포, 대공미사일, 전투기가 항공 유닛에 주는 피해 +40%, 시야 +2, 생산비 −25%. 자주대공포가 지상 유닛에 주는 피해 +40%, 방어 +15%, 이동력 +1. 헬기, 공격기, 폭격기 공격 −15%.',
  '潜艇攻击 +40%、造价 −20%，只有相邻时才会被发现。驱逐舰、炮艇攻击 +20%、造价 −15%。步兵类单位攻击 +25%，车辆攻击 +10%。': '잠수함 공격 +40%, 생산비 −20%, 인접해야만 발견된다. 구축함, 고속정 공격 +20%, 생산비 −15%. 보병류 유닛 공격 +25%, 차량 공격 +10%.',
  '侦察车、摩托兵、运兵车移动力 +3。侦察车、摩托兵攻击 +60%，攻击后可用剩余移动力再移动。中型、重型坦克造价 +10%。': '정찰차, 바이크병, 수송차 이동력 +3. 정찰차, 바이크병 공격 +60%, 공격 후 남은 이동력으로 재이동 가능. 중형전차, 중전차 생산비 +10%.',
  '喷火兵、破甲兵攻击 +50%、移动力 +1、造价 −20%。远程单位攻击 −10%。': '화염방사병, 대전차병 공격 +50%, 이동력 +1, 생산비 −20%. 원거리 유닛 공격 −10%.',
  '己方单位在能进入的地形上移动消耗都是 1。步兵类单位移动力 +1。': '아군 유닛은 진입 가능한 지형에서 이동 비용 모두 1. 보병류 유닛 이동력 +1.',
  '己方单位的攻击不随 HP 减少而降低。修理费 ×2。': '아군 유닛의 공격은 HP가 줄어도 낮아지지 않는다. 수리비 ×2.',
  '己方城市也可以生产步兵类单位。步兵类单位造价 −20%、攻击 +10%。': '아군 도시에서도 보병류 유닛 생산 가능. 보병류 유닛 생산비 −20%, 공격 +10%.',
  '各型坦克、深渊战车、装甲列车攻击 +15%。位于陨星矿、荒地、废墟的己方单位防御 +20%，每回合恢复 1 HP。己方陨星矿收入 +50%。': '경전차, 중형전차, 중전차, 심연 전차, 장갑열차 공격 +15%. 운석 광산, 황무지, 폐허에 있는 아군 유닛 방어 +20%, 매 턴 HP 1 회복. 아군 운석 광산 수입 +50%.',
  '舰船攻击 +20%、移动力 +1。远程单位攻击 +15%。己方单位在沙滩上的移动消耗为 1。迷雾开启时，视野范围内海洋、沙滩、礁石上的敌方单位都可见，礁石的隐蔽对其无效（潜艇除外）。': '함선 공격 +20%, 이동력 +1. 원거리 유닛 공격 +15%. 아군 유닛의 해변 이동 비용은 1. 안개가 켜져 있으면 시야 안의 바다, 해변, 암초에 있는 적군 유닛이 모두 보이며, 암초의 은폐가 통하지 않는다(잠수함 제외).',
  '所有单位造价 −15%。每击毁一个敌方单位，获得它造价 30% 的资金。': '모든 유닛 생산비 −15%. 적군 유닛을 하나 격파할 때마다 그 생산비의 30%를 자금으로 획득.',
  '车辆攻击 +10%，在道路、桥梁上防御 +15%。回合开始时位于道路、桥梁的车辆本回合移动力 +2。装甲列车造价 −20%。': '차량 공격 +10%, 도로, 다리에서는 방어 +15%. 턴 시작 시 도로, 다리에 있는 차량은 이번 턴 이동력 +2. 장갑열차 생산비 −20%.',
  '汀鹭的修理本来就免费，只有“额外恢复 1 HP”有效': '정로의 수리는 원래 무료이므로 “HP 1 추가 회복”만 유효',
  '每座兵工厂每回合可生产 2 个单位（要先把第一个单位移出建筑）；重型坦克造价 −20%。': '공장마다 매 턴 유닛 2개 생산 가능(첫 유닛을 먼저 건물 밖으로 옮겨야 함). 중전차 생산비 −20%.',
  '沧澜的舰船在港口修理本来就免费，只有“舰船造价 −10%”有效': '창란의 함선은 원래 항구에서 수리 무료이므로 “함선 생산비 −10%”만 유효',
  '步兵类单位在森林、山地、沼泽上的移动消耗都是 1。': '보병류 유닛은 숲, 산지, 늪에서 이동 비용 모두 1.',
  '雪杉的单位在可进入地形上的移动消耗本来就都是 1': '설삼의 유닛은 원래 진입 가능한 지형에서 이동 비용 모두 1',
  '每个己方回合开始时，己方城市、司令部、碉堡使相邻且可见的敌方单位各损失 1 HP（不会被击毁；每个单位每回合只受一次）。': '매 아군 턴 시작 시 아군 도시, 사령부, 벙커에 인접해 있고 보이는 적군 유닛이 각각 HP 1 손실(격파되지 않음. 유닛마다 턴당 한 번만).',
  '侦察车、轻型坦克、防空车移动力再 +1。': '정찰차, 경전차, 자주대공포 이동력 추가 +1.',
  '运兵车移动力 +1、搭载数 +1。步兵类单位的攻击减益减为 −5%。': '수송차 이동력 +1, 탑재 수 +1. 보병류 유닛의 공격 페널티가 −5%로 감소.',
  '强化技能「闪击」，其他效果保留。本回合：侦察车、防空车和各型坦克击毁目标后可再行动一次，全军最多 4 次。': '스킬 “전격” 강화. 다른 효과는 유지. 이번 턴: 정찰차, 자주대공포, 경전차, 중형전차, 중전차는 목표 격파 후 한 번 더 행동 가능. 전군 합쳐 최대 4회.',
  '远程单位的运气范围变为 5–9（原来 0–9）。自行火炮、火箭炮视野 +2。': '원거리 유닛의 행운 범위가 5–9로 변경(원래 0–9). 자주포, 로켓포 시야 +2.',
  '自行火炮移动后可以攻击距离 2 格的目标，这次攻击 −30%。': '자주포는 이동 후 거리 2칸의 목표 공격 가능. 이 공격은 −30%.',
  '强化技能「炮火覆盖」，其他效果保留。本回合：己方远程单位射程 +1。': '스킬 “융단 포격” 강화. 다른 효과는 유지. 이번 턴: 아군 원거리 유닛 사거리 +1.',
  '各型坦克在森林、废墟、荒地上的移动消耗为 1。': '경전차, 중형전차, 중전차는 숲, 폐허, 황무지에서 이동 비용 1.',
  '与己方坦克相邻的其他陆上单位，攻击和反击时没有攻击 −15% 的减益。': '아군 전차에 인접한 다른 지상 유닛은 공격과 반격 시 공격 −15% 페널티가 없다.',
  '强化技能「履带洪流」，其他效果保留。发动时，最多 2 座没有单位的己方兵工厂各出现一辆 5 HP 的轻型坦克，当回合可行动。': '스킬 “궤도 격류” 강화. 다른 효과는 유지. 발동 시 유닛이 없는 아군 공장 최대 2곳에 HP 5의 경전차가 한 대씩 출현. 그 턴에 행동 가능.',
  '己方单位被敌方击毁时，返还它造价的 10%。': '아군 유닛이 적군에게 격파되면 그 생산비의 10% 반환.',
  '强化技能「加班」，其他效果保留。本回合：单位造价 −40%，每座生产建筑可生产 3 次。': '스킬 “야근” 강화. 다른 효과는 유지. 이번 턴: 유닛 생산비 −40%, 생산 건물마다 3회 생산 가능.',
  '主动攻击 HP 比自己低的敌方单位时，没有攻击 −10% 的减益。': '자신보다 HP가 낮은 적군 유닛을 선공할 때 공격 −10% 페널티가 없다.',
  '不发动技能时，喷火兵攻击后也会把目标所在的森林变为荒地。': '스킬을 발동하지 않았을 때도 화염방사병이 공격하면 목표가 있는 숲이 황무지로 변한다.',
  '强化技能「燎原」，其他效果保留。本回合：破甲兵攻击也有溅射。每个敌方单位每回合因溅射最多损失 5 HP。': '스킬 “들불” 강화. 다른 효과는 유지. 이번 턴: 대전차병의 공격에도 스플래시 발생. 적군 유닛마다 스플래시로 턴당 최대 HP 5 손실.',
  '舰船在礁石上的移动消耗为 1。位于礁石、港口的舰船防御 +10%。': '함선은 암초에서 이동 비용 1. 암초, 항구에 있는 함선 방어 +10%.',
  '登陆艇搭载数 +1。位于沙滩的己方陆上单位防御 +20%。': '상륙정 탑재 수 +1. 해변에 있는 아군 지상 유닛 방어 +20%.',
  '强化技能「怒潮」，其他效果保留。本回合：战列舰移动后可以攻击，射程 2–4。': '스킬 “노도” 강화. 다른 효과는 유지. 이번 턴: 전함은 이동 후에도 공격 가능, 사거리 2–4.',
  '攻击机、轰炸机、战斗机也可以在己方城市修理。': '공격기, 폭격기, 전투기는 아군 도시에서도 수리 가능.',
  '强化技能「俯冲」，其他效果保留。己方下回合开始前：只有敌方战斗机、防空导弹、防空车能攻击己方攻击机、轰炸机、战斗机。': '스킬 “급강하” 강화. 다른 효과는 유지. 다음 아군 턴 시작 전까지: 적군 전투기, 대공미사일, 자주대공포만 아군 공격기, 폭격기, 전투기를 공격할 수 있다.',
  '直升机可以发现周围 8 格森林、废墟中的隐蔽单位。武装直升机对步兵类单位伤害 +10%。': '헬기는 주위 8칸의 숲, 폐허에 있는 은폐 유닛 발견 가능. 공격 헬기가 보병류 유닛에 주는 피해 +10%.',
  '回合开始时已在运输直升机上的步兵类单位，卸载后当回合还能攻击或占领，但不能移动。': '턴 시작 시 이미 수송 헬기에 타고 있던 보병류 유닛은 하차한 턴에도 공격 또는 점령 가능. 단, 이동 불가.',
  '强化技能「蜂群」，其他效果保留。本回合：武装直升机攻击时，目标每与一架己方直升机相邻，攻击 +10%，最多 +30%。': '스킬 “벌떼” 강화. 다른 효과는 유지. 이번 턴: 공격 헬기가 공격할 때 목표에 인접한 아군 헬기 한 대마다 공격 +10%, 최대 +30%.',
  '回合开始时，HP 不高于 4 的单位多恢复 1 HP。': '턴 시작 시 HP 4 이하인 유닛은 HP 1 추가 회복.',
  '满 HP 的己方单位没有攻击 −10% 的减益。': '최대 HP인 아군 유닛은 공격 −10% 페널티가 없다.',
  '强化技能「急救」，其他效果保留。恢复量提高到 3 HP。复活最近被击毁的 2 个单位，各 4 HP。每个单位每局只能复活一次。': '스킬 “응급 처치” 강화. 다른 효과는 유지. 회복량이 HP 3으로 증가. 가장 최근에 격파된 유닛 2개를 각각 HP 4로 부활. 유닛마다 게임당 한 번만 부활 가능.',
  '防空导弹射程 +1。防空车、防空导弹、战斗机视野再 +1。': '대공미사일 사거리 +1. 자주대공포, 대공미사일, 전투기 시야 추가 +1.',
  '强化技能「天网」，其他效果保留。被“天网”攻击的敌方航空单位立即结束行动。': '스킬 “천망” 강화. 다른 효과는 유지. “천망”의 공격을 받은 적군 항공 유닛은 즉시 행동 종료.',
  '上回合没有移动的潜艇，本回合第一次攻击 +20%。': '지난 턴에 이동하지 않은 잠수함은 이번 턴 첫 공격 +20%.',
  '潜艇攻击后可用剩余移动力再移动。': '잠수함은 공격 후 남은 이동력으로 재이동 가능.',
  '强化技能「狼群」，其他效果保留。本回合：潜艇可以穿过敌方舰船所在的格子。': '스킬 “늑대 떼” 강화. 다른 효과는 유지. 이번 턴: 잠수함은 적군 함선이 있는 칸 통과 가능.',
  '强化技能「全民皆兵」，其他效果保留。出现步兵的城市增加到最多 6 座，步兵初始为 1 星。': '스킬 “전민개병” 강화. 다른 효과는 유지. 보병이 출현하는 도시가 최대 6곳으로 증가. 보병은 초기 1성.',
  '投弹手击毁目标后也可再行动（每回合一次）。': '척탄병도 목표 격파 후 재행동 가능(턴당 한 번).',
  '狙击手被相邻的敌方单位攻击时可以反击，伤害是正常的 50%。': '저격수는 인접한 적군 유닛에게 공격받으면 반격 가능. 피해는 평소의 50%.',
  '强化技能「一击」，其他效果保留。本回合：每个狙击手击毁目标后可连续再行动，最多 3 次。': '스킬 “일격” 강화. 다른 효과는 유지. 이번 턴: 저격수마다 목표 격파 후 연속으로 재행동 가능, 최대 3회.',
  '敌方单位遇伏时，伏击它的己方单位先攻击一次，不受反击。每个己方单位每个敌方回合一次。': '적군 유닛이 매복 조우하면, 매복한 아군 유닛이 먼저 한 번 공격하고 반격받지 않는다. 아군 유닛마다 적군 턴당 한 번.',
  '强化技能「灯火管制」，其他效果保留。持续时间延长到 2 个敌方回合。迷雾关闭时，敌方只能发现相邻的己方单位。生效期间技能槽不积累。': '스킬 “등화관제” 강화. 다른 효과는 유지. 지속 시간이 적군 턴 2회로 연장. 안개가 꺼져 있으면 적군은 인접한 아군 유닛만 발견 가능. 효과 중에는 스킬 게이지가 축적되지 않는다.',
  '攻击后再移动时，剩余移动力 +1。': '공격 후 재이동할 때 남은 이동력 +1.',
  '攻击后再移动过的单位，己方下回合开始前防御 +15%。': '공격 후 재이동한 유닛은 다음 아군 턴 시작 전까지 방어 +15%.',
  '强化技能「风驰」，其他效果保留。本回合：全军移动力提高到 +3，直射单位攻击后可用全部移动力再移动。': '스킬 “질풍” 강화. 다른 효과는 유지. 이번 턴: 전군 이동력이 +3으로 증가. 직사 유닛은 공격 후 이동력 전부로 재이동 가능.',
  '履带车辆可以进入河流，轮式车辆可以进入沼泽，移动消耗都是 2。': '궤도 차량은 강에, 차륜 차량은 늪에 진입 가능. 이동 비용은 모두 2.',
  '强化技能「寒潮」，其他效果保留。生效期间：敌方单位在森林、山地、荒地、沼泽、河流上的移动消耗 +1（航空单位除外）。': '스킬 “한파” 강화. 다른 효과는 유지. 효과 중: 적군 유닛은 숲, 산지, 황무지, 늪, 강에서 이동 비용 +1(항공 유닛 제외).',
  '己方单位的地形防御也不随 HP 减少而降低。': '아군 유닛의 지형 방어도 HP가 줄어도 낮아지지 않는다.',
  '每个敌方回合，第一个要被击毁的己方单位保留 1 HP。受攻击前 HP 至少为 5 才有效，每个单位每局一次。': '적군 턴마다, 격파될 첫 번째 아군 유닛이 HP 1을 유지. 공격받기 전 HP가 5 이상이어야 적용. 유닛마다 게임당 한 번.',
  '强化技能「背水」，其他效果保留。攻击加成改为每损失 1 HP +10%，最多 +90%。己方下回合开始前：“咬牙”每个敌方回合可触发 3 次。': '스킬 “배수진” 강화. 다른 효과는 유지. 공격 보너스가 HP 1 손실마다 +10%, 최대 +90%로 변경. 다음 아군 턴 시작 전까지: “이 악물기”가 적군 턴마다 3회 발동 가능.',
  '位于己方建筑的单位每回合免费恢复 1 HP（航空单位除外）。': '아군 건물에 있는 유닛은 매 턴 HP 1 무료 회복(항공 유닛 제외).',
  '位于 2 星及以上地形或建筑的单位反击时，没有攻击 −10% 的减益。': '2성 이상 지형 또는 건물에 있는 유닛은 반격 시 공격 −10% 페널티가 없다.',
  '强化技能「铁壁」，其他效果保留。恢复量提高到 3 HP。己方下回合开始前：敌方的占领不会减少己方建筑的占领值。': '스킬 “철벽” 강화. 다른 효과는 유지. 회복량이 HP 3으로 증가. 다음 아군 턴 시작 전까지: 적군이 점령을 시도해도 아군 건물의 점령치가 줄지 않는다.',
  '所有单位造价再 −5%，结果向下取整到 10 的倍数。': '모든 유닛 생산비 추가 −5%. 결과는 10의 배수로 내림.',
  '回合开始时，每持有 500 资金获得 20 资金，最多 200（上限随地图规模变化）。': '턴 시작 시 보유 자금 500마다 자금 20 획득, 최대 200(상한은 맵 규모에 따라 달라진다).',
  '强化技能「军费」，其他效果保留。每座建筑的资金提高到 100。本回合：单位造价再 −20%。': '스킬 “군자금” 강화. 다른 효과는 유지. 건물 하나당 자금이 100으로 증가. 이번 턴: 유닛 생산비 추가 −20%.',
  '运气范围变为 −5 至 +55（原来 0 至 +40）。': '행운 범위가 −5 ~ +55로 변경(원래 0 ~ +40).',
  '强化技能「梭哈」，其他效果保留。本回合：运气范围 ×1.5。': '스킬 “올인” 강화. 다른 효과는 유지. 이번 턴: 행운 범위 ×1.5.',
  '侦察车可以占领建筑，占领值减半。不能使用导弹井。': '정찰차도 건물 점령 가능, 점령치 절반. 미사일 사일로는 사용 불가.',
  '强化技能「穿插」，其他效果保留。被侦察车、摩托兵、运兵车穿过的敌方陆上单位各损失 1 HP（不会被击毁），每回合最多 2 HP。': '스킬 “침투” 강화. 다른 효과는 유지. 정찰차, 바이크병, 수송차가 통과한 적군 지상 유닛은 각각 HP 1 손실(격파되지 않음), 턴당 최대 HP 2.',
  '己方单位正在占领的敌方建筑，本回合不给敌方提供收入。': '아군 유닛이 점령 중인 적군 건물은 이번 턴 적군에게 수입을 제공하지 않는다.',
  '强化技能「加征」，其他效果保留。获得的收入提高到 150%。本回合：占领中立建筑时占领值 ×2。': '스킬 “추가 징수” 강화. 다른 효과는 유지. 획득하는 수입이 150%로 증가. 이번 턴: 중립 건물을 점령할 때 점령치 ×2.',
  '己方城市还可以生产侦察车和运兵车。': '아군 도시에서 정찰차와 수송차도 생산 가능.',
  '不发动技能时，每回合也可以出售 1 个位于己方建筑的单位，返还造价的 40%。': '스킬을 발동하지 않았을 때도 매 턴 아군 건물에 있는 유닛 1개 매각 가능. 생산비의 40% 반환.',
  '强化技能「黑市」，其他效果保留。本回合：在己方城市生产的单位当回合可行动。': '스킬 “암시장” 강화. 다른 효과는 유지. 이번 턴: 아군 도시에서 생산한 유닛은 그 턴에 행동 가능.',
});

