  '本回合：全军移动力 +1。侦察车、摩托兵攻击 +40%，其他单位攻击 +20%。侦察车、摩托兵、运兵车可以穿过敌方单位，但不能停在敌方单位所在的格子。': '이번 턴: 전군 이동력 +1. 정찰차, 바이크병 공격 +40%, 그 외 유닛 공격 +20%. 정찰차, 바이크병, 수송차는 적군 유닛을 통과할 수 있다. 단, 적군 유닛이 있는 칸에 머물 수는 없다.',
  '本回合：步兵类单位攻击 +40%，其他单位攻击 +20%。喷火兵攻击后，目标所在的森林变为荒地，周围 2 格内的敌方单位各损失 3 HP（不会被击毁）。': '이번 턴: 보병류 유닛 공격 +40%, 그 외 유닛 공격 +20%. 화염방사병이 공격하면 목표가 있는 숲이 황무지로 변하고, 주위 2칸 안의 적군 유닛이 각각 HP 3 손실(격파되지 않음).',
  '本回合：可以出售任意己方单位，返还造价的 90%（与剩余 HP 无关）。': '이번 턴: 아군 유닛을 자유롭게 매각 가능. 생산비의 90% 반환(남은 HP와 무관).',
  '在己方回合可以研究科技。': '아군 턴에 기술 연구 가능.',
  '各档研究经费 −50%，每回合研究点 −2；上回合新占领过建筑时（每座建筑每局只算一次），本回合研究点 +4。': '각 단계 연구비 −50%, 매 턴 연구 포인트 −2. 지난 턴에 건물을 새로 점령했으면(건물마다 게임당 한 번만 계산) 이번 턴 연구 포인트 +4.',
  '强化技能「架盾」，其他效果保留。己方下回合开始前：敌方陆上单位、舰船移动到与己方直射单位相邻的格子时，先受到 50% 伤害的攻击（不会被击毁）。每个己方单位只攻击一次，敌方单位每次移动最多受到 2 次。': '스킬 “방패 태세” 강화. 다른 효과는 유지. 다음 아군 턴 시작 전까지: 적군 지상 유닛, 함선이 아군 직사 유닛 옆으로 이동해 오면 먼저 피해 50%의 공격을 받는다(격파되지 않음). 아군 유닛마다 한 번만 공격하고, 적군 유닛은 이동 한 번에 최대 2회 받는다.',
  '只有步兵这一个兵种可以穿过敌方单位所在的格子，但不能停在上面。': '병종 보병만 적군 유닛이 있는 칸을 통과할 수 있다. 단, 그 칸에 머물 수는 없다.',
  '每占领一座建筑，技能槽 +10%，每回合最多 +20%。每座建筑每局只算一次，技能生效期间不算。': '건물을 하나 점령할 때마다 스킬 게이지 +10%, 턴당 최대 +20%. 건물마다 게임당 한 번만 계산하며, 스킬 효과 중에는 계산하지 않는다.',
