  '每回合提供 100 资金。停留的己方陆上单位每回合恢复 2 HP（需支付资金）。被敌方占领时，己方败北。': '매 턴 자금 100 제공. 머무는 아군 지상 유닛은 매 턴 HP 2 회복(자금 지불 필요). 적군에게 점령되면 아군 패배.',
  '大闸的机房。停留的己方步兵类单位每回合恢复 2 HP（需支付资金）。在会涨水的关卡中，每占有一座闸房，下一次涨水推迟 1 天；全部占有时停止涨水。': '대수문의 기계실. 머무는 아군 보병류 유닛은 매 턴 HP 2 회복(자금 지불 필요). 수위가 오르는 스테이지에서는 수문실을 1곳 보유할 때마다 다음 수위 상승이 1일 늦어진다. 전부 보유하면 수위 상승이 멈춘다.',
